-- Rollback-only fixture checks for the corrected production schema.
begin;
do $$declare emp bigint; item_key bigint; part_type bigint; part_key bigint; second_part bigint; named_variant bigint; variant_link bigint; size_key bigint; item_size bigint; type_key bigint; stage_key bigint; pp_key bigint; status_key bigint; job_key bigint; pp_job bigint; link_key bigint; actual numeric; caught boolean;begin
 select id into strict emp from garments_erp.employee where employee_code='SCE/00001';
 select id into strict status_key from garments_erp.item_status_list where status='Yet to start';
 insert into garments_erp.item(style_code) values('ROLLBACK-PRODUCTION-CHECK') returning id into item_key;
 insert into garments_erp.part_list(part) values('Rollback part '||gen_random_uuid()::text) returning id into part_type;
 insert into garments_erp.item_part(item_id,part_list_id) values(item_key,part_type) returning id into part_key;
 insert into garments_erp.item_part(item_id,part_list_id) values(item_key,part_type) returning id into second_part;
 insert into garments_erp.variant(variant_name,share_weight) values('Rollback variant',1) returning id into named_variant;
 insert into garments_erp.variant_item(item_part_id,variant_id) values(part_key,named_variant) returning id into variant_link;
 caught:=false;begin update garments_erp.variant set share_weight=0 where id=named_variant;exception when check_violation then caught:=true;end;
 if not caught then raise exception 'TEST: zero variant weight accepted';end if;
 insert into garments_erp.size_list(size,sort_order) values('ROLLBACK-'||gen_random_uuid()::text,2147483000) returning id into size_key;
 insert into garments_erp.item_size_list(item_id,size_list_id) values(item_key,size_key) returning id into item_size;
 insert into garments_erp.stage_type(name) values('ROLLBACK-'||gen_random_uuid()::text) returning id into type_key;
 insert into garments_erp.stage(name,abbr,sort_order,stage_type_id,track_pieces,pp_stage) values('ROLLBACK-PROD-'||gen_random_uuid()::text,'RT'||substr(gen_random_uuid()::text,1,8),2147483000,type_key,true,false) returning id into stage_key;
 insert into garments_erp.stage(name,abbr,sort_order,stage_type_id,track_pieces,pp_stage) values('ROLLBACK-PP-'||gen_random_uuid()::text,'RP'||substr(gen_random_uuid()::text,1,8),2147483001,type_key,false,true) returning id into pp_key;
 caught:=false;begin update garments_erp.stage set track_pieces=true where id=pp_key;exception when check_violation then caught:=true;end;
 if not caught then raise exception 'TEST: PP stage tracked pieces';end if;
 caught:=false;begin insert into garments_erp.job(item_part_id,stage_id,item_status_list_id,job_code) values(part_key,stage_key,status_key,'ROLLBACK-'||gen_random_uuid()::text);exception when not_null_violation then caught:=true;end;
 if not caught then raise exception 'TEST: job without verifier accepted';end if;
 insert into garments_erp.job(item_part_id,stage_id,item_status_list_id,verify_employee_id,job_code) values(part_key,stage_key,status_key,emp,'ROLLBACK-'||gen_random_uuid()::text) returning id into job_key;
 insert into garments_erp.variant_item_per_job(job_id,variant_item_id) values(job_key,variant_link) returning id into link_key;
 insert into garments_erp.stage_pieces(variant_item_per_job_id,item_size_list_id,pieces_stock_in) values(link_key,item_size,100) returning pieces_stock_out into actual;
 if actual<>0 then raise exception 'TEST: output did not default to zero';end if;
 insert into garments_erp.production_checklist(item_id,fpt_gpt_status_id) values(item_key,status_key);
 insert into garments_erp.job_assignees(job_id,assigned_employees_id) values(job_key,emp);
 caught:=false;begin insert into garments_erp.job_assignees(job_id,assigned_employees_id) values(job_key,emp);exception when unique_violation then caught:=true;end;
 if not caught then raise exception 'TEST: duplicate assignee accepted';end if;
 set constraints all immediate;
 caught:=false;begin update garments_erp.job set stage_id=pp_key where id=job_key;exception when raise_exception then caught:=true;end;
 if not caught then raise exception 'TEST: existing job stage changed';end if;
 caught:=false;begin update garments_erp.job set item_part_id=second_part where id=job_key;exception when raise_exception then caught:=true;end;
 if not caught then raise exception 'TEST: wrong part variant accepted';end if;
 insert into garments_erp.job(item_part_id,stage_id,item_status_list_id,verify_employee_id,job_code) values(part_key,pp_key,status_key,emp,'ROLLBACK-'||gen_random_uuid()::text) returning id into pp_job;
 insert into garments_erp.variant_item_per_job(job_id,variant_item_id) values(pp_job,variant_link) returning id into link_key;
 caught:=false;begin insert into garments_erp.stage_pieces(variant_item_per_job_id,item_size_list_id) values(link_key,item_size);exception when raise_exception then caught:=true;end;
 if not caught then raise exception 'TEST: PP stage piece row accepted';end if;
 if exists(select 1 from pg_constraint where conrelid='garments_erp.production_checklist'::regclass and contype='f' and conname<>'production_checklist_item_id_fkey' and confrelid<>'garments_erp.item_status_list'::regclass) then raise exception 'TEST: checklist status target incorrect';end if;
end$$;
rollback;
